from pathlib import Path
import re

p = Path('index.html')
s = p.read_text(encoding='utf-8')

# Extra styles for the richer detail page.
anchor = '.trend-source{font-size:9px;color:var(--muted);margin-top:8px}'
extra = '''.trend-source{font-size:9px;color:var(--muted);margin-top:8px}.detail-kpis{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.detail-kpi{background:#101720;border:1px solid var(--line);border-radius:12px;padding:10px}.detail-kpi-label{font-size:9px;color:var(--muted)}.detail-kpi-value{font-size:18px;font-weight:850;margin-top:2px}.analysis-list{display:grid;gap:7px}.analysis-item{padding:9px 10px;border-radius:11px;background:#101720;border:1px solid var(--line);font-size:12px;line-height:1.4}.analysis-item.good{border-color:#286443;color:#c4f5d4}.analysis-item.bad{border-color:#713737;color:#ffc0c0}.analysis-item.watch{border-color:#705321;color:#ffe0aa}.announcement{padding:10px 0;border-bottom:1px solid var(--line)}.announcement:last-child{border-bottom:0}.announcement-date{font-size:9px;color:var(--muted)}.announcement-title{font-size:12px;line-height:1.4;margin-top:3px}.price-sensitive{display:inline-block;margin-left:5px;padding:2px 5px;border-radius:999px;background:#5b2b2b;color:#ffb7b7;font-size:8px;font-weight:850}.holding-card:not(.editing){cursor:pointer}.tap-more{font-size:9px;color:#8fd8ff;margin-top:4px}'''
if anchor in s and '.detail-kpis{' not in s:
    s = s.replace(anchor, extra, 1)

old_detail = '<section class="page" id="detail"><button class="back" id="back">‹ Back</button><div class="detail-head"><div><div class="detail-ticker" id="detailTicker"></div><div class="company" id="detailName"></div></div><div class="detail-score" id="detailScore"></div></div><div class="tags" id="detailTags"></div><div class="panel"><div class="panel-title">Current call</div><p id="detailCall"></p></div><div class="panel"><div class="panel-title">Global trends</div><div id="detailGlobalTrend"></div></div><div class="panel"><div class="panel-title">Why this could outperform</div><p id="detailThesis"></p></div><div class="panel"><div class="panel-title">Why now</div><p id="detailCatalyst"></p></div><div class="panel"><div class="panel-title">What could prove it wrong</div><p id="detailRisk"></p></div><div class="panel"><div class="panel-title">Score anatomy</div><div class="score-grid" id="scoreGrid"></div></div><div class="panel"><div class="panel-title">Recent changes</div><div id="timeline"></div></div></section>'
new_detail = '<section class="page" id="detail"><button class="back" id="back">‹ Back</button><div class="detail-head"><div><div class="detail-ticker" id="detailTicker"></div><div class="company" id="detailName"></div></div><div class="detail-score" id="detailScore"></div></div><div class="tags" id="detailTags"></div><div class="panel"><div class="panel-title">Current call</div><p id="detailCall"></p></div><div class="panel"><div class="panel-title">Company snapshot</div><div class="detail-kpis" id="companySnapshot"></div></div><div class="panel"><div class="panel-title">Price & market performance</div><div class="detail-kpis" id="performanceGrid"></div></div><div class="panel"><div class="panel-title">Analysis</div><div class="analysis-list" id="companyAnalysis"></div></div><div class="panel"><div class="panel-title">Global trends</div><div id="detailGlobalTrend"></div></div><div class="panel"><div class="panel-title">Why this could outperform</div><p id="detailThesis"></p></div><div class="panel"><div class="panel-title">Why now</div><p id="detailCatalyst"></p></div><div class="panel"><div class="panel-title">What could prove it wrong</div><p id="detailRisk"></p></div><div class="panel"><div class="panel-title">Recent ASX announcements</div><div id="detailAnnouncements"></div></div><div class="panel"><div class="panel-title">Score anatomy</div><div class="score-grid" id="scoreGrid"></div></div><div class="panel"><div class="panel-title">Recent score changes</div><div id="timeline"></div></div></section>'
if old_detail not in s:
    raise SystemExit('detail section anchor not found')
s = s.replace(old_detail, new_detail, 1)

# Make the complete saved holding card open the company detail page.
s = s.replace('return `<div class="stock ${r.className} holding-card ${editing?"editing":""}">', 'return `<div class="stock ${r.className} holding-card ${editing?"editing":""}" ${p.ticker?`data-open="${p.ticker}"`:""}>', 1)
s = s.replace('${st?`${money(price)} · Opportunity ${st.opp}`:"Waiting for scanner"}</div></div><div class="action', '${st?`${money(price)} · Opportunity ${st.opp}<div class="tap-more">Tap for full company analysis ›</div>`:"Waiting for scanner"}</div></div><div class="action', 1)

# Add analysis helper functions before openDetail.
marker = 'function openDetail(t){'
helpers = r'''function metricPct(v){const n=Number(v);return isFinite(n)?pctText(n):"—"}
function detailKpi(label,value,cls=""){return `<div class="detail-kpi"><div class="detail-kpi-label">${label}</div><div class="detail-kpi-value ${cls}">${value}</div></div>`}
function buildCompanyAnalysis(s){const good=[],bad=[],watch=[];const r1=Number(s.relative1m||0),r3=Number(s.relative3m||0),mom=Number(s.momentum||0),vol=Number(s.volumeRatio||0),ann=Number(s.announcementSignal||0),risk=Number(s.risk||0),dd=Number(s.drawdown60||0),gt=Number(s.globalTrendScore||0),shorts=Number(s.shortInterestPct);if(r1>=5)good.push(`Beating the ASX 200 by ${r1.toFixed(1)}% over 1 month.`);if(r3>=8)good.push(`Strong 3-month relative strength of ${r3.toFixed(1)}% versus the ASX 200.`);if(mom>=65)good.push(`Momentum score is strong at ${Math.round(mom)}/100.`);if(vol>=1.25)good.push(`Trading volume is ${vol.toFixed(2)}× its recent average, showing increased market attention.`);if(ann>=10)good.push(`Recent ASX announcements are positively scored at +${Math.round(ann)}.`);if(gt>=12)good.push(`Global-news themes are supportive with a trend score of +${Math.round(gt)}.`);if(isFinite(shorts)&&shorts<=2)good.push(`Short interest is low at ${shorts.toFixed(1)}%, so there is little bearish positioning pressure.`);if(r1<=-5)bad.push(`Underperforming the ASX 200 by ${Math.abs(r1).toFixed(1)}% over 1 month.`);if(r3<=-8)bad.push(`Weak 3-month relative strength of ${r3.toFixed(1)}% versus the ASX 200.`);if(risk>=60)bad.push(`Risk score is elevated at ${Math.round(risk)}/100.`);if(dd>=20)bad.push(`Recent drawdown has reached ${dd.toFixed(1)}%, showing meaningful price instability.`);if(ann<=-10)bad.push(`Recent ASX announcement signal is negative at ${Math.round(ann)}.`);if(isFinite(shorts)&&shorts>=8)bad.push(`Short interest is high at ${shorts.toFixed(1)}%, a significant bearish counter-signal.`);if(gt<=-12)bad.push(`Global-news themes are currently a headwind with a score of ${Math.round(gt)}.`);if(!good.length)watch.push('No single bullish factor is dominant yet; the current case relies on the combined score rather than one strong catalyst.');if(vol<1)watch.push('Volume is below its recent average, so confirmation from stronger participation would improve the case.');if(Math.abs(r1)<3)watch.push('Relative performance versus the ASX 200 is still close to neutral; watch for a clear break higher or lower.');watch.push(`Next review: watch opportunity score, ASX announcements, short interest, global themes and relative strength for confirmation or deterioration.`);return {good,bad,watch}}
'''
if marker not in s:
    raise SystemExit('openDetail marker not found')
s = s.replace(marker, helpers + marker, 1)

# Replace openDetail with richer version.
pat = re.compile(r'function openDetail\(t\)\{.*?showPage\("detail"\)\}', re.S)
new_open = r'''function openDetail(t){const s=stockOf(t);if(!s)return;previousPage=document.querySelector('.page.active').id;const r=recommendation(s),sh=shortSignal(s),co=callOutcome(s);$("#detailTicker").textContent=s.ticker;$("#detailName").textContent=(s.name&&s.name!==s.ticker?`${s.name} · ${money(s.price)}`:money(s.price));$("#detailScore").innerHTML=`${s.opp}<small>OPPORTUNITY</small>`;$("#detailTags").innerHTML=`<span class="tag ${r.className==="buy"?"green":r.className==="sell"?"red":"blue"}">${r.label}</span><span class="tag">${s.edge||s.opportunitySource||"ASX"}</span><span class="tag">Risk ${s.risk}</span><span class="tag">Confidence ${s.confidence??"—"}</span><span class="tag ${sh.className}">${sh.label}</span>`;$("#detailCall").textContent=r.reason+(co?` Tracking: ${co.days}/${co.horizon} days, ${pctText(co.ret)} since the call.`:"");$("#companySnapshot").innerHTML=[detailKpi("Current price",money(s.price)),detailKpi("Opportunity",`${Math.round(Number(s.opp||0))}/100`),detailKpi("Whole-ASX rank",s.wholeAsxRank?`#${s.wholeAsxRank}`:"—"),detailKpi("20d turnover",s.wholeAsxDollarTurnover20d?money(s.wholeAsxDollarTurnover20d):"—"),detailKpi("Confidence",`${Math.round(Number(s.confidence||0))}/100`),detailKpi("Short interest",isFinite(Number(s.shortInterestPct))?`${Number(s.shortInterestPct).toFixed(1)}%`:"N/A")].join("");$("#performanceGrid").innerHTML=[detailKpi("5 days",metricPct(s.return5d),Number(s.return5d)>=0?"up":"down"),detailKpi("1 month",metricPct(s.return1m),Number(s.return1m)>=0?"up":"down"),detailKpi("3 months",metricPct(s.return3m),Number(s.return3m)>=0?"up":"down"),detailKpi("6 months",metricPct(s.return6m),Number(s.return6m)>=0?"up":"down"),detailKpi("12 months",metricPct(s.return12m),Number(s.return12m)>=0?"up":"down"),detailKpi("vs ASX 200 · 1m",metricPct(s.relative1m),Number(s.relative1m)>=0?"up":"down"),detailKpi("vs ASX 200 · 3m",metricPct(s.relative3m),Number(s.relative3m)>=0?"up":"down"),detailKpi("Volume ratio",isFinite(Number(s.volumeRatio))?`${Number(s.volumeRatio).toFixed(2)}×`:"—")].join("");const ca=buildCompanyAnalysis(s);$("#companyAnalysis").innerHTML=[...ca.good.map(x=>`<div class="analysis-item good"><b>BULL:</b> ${x}</div>`),...ca.bad.map(x=>`<div class="analysis-item bad"><b>RISK:</b> ${x}</div>`),...ca.watch.map(x=>`<div class="analysis-item watch"><b>WATCH:</b> ${x}</div>`)].join("");const gt=globalTrendInfo(s);$("#detailGlobalTrend").innerHTML=gt.themes.length?`<div class="global-chip ${gt.className}">${gt.signal} · score ${gt.score>=0?"+":""}${gt.score} · opportunity ${gt.adj>=0?"+":""}${gt.adj}</div><div class="global-box">${gt.themes.slice(0,3).map(t=>`<div class="global-theme-row"><div class="global-theme-name">${t.theme} · ${Number(t.score)>=0?"+":""}${t.score}</div><div class="source-badge">${t.direction||"NEUTRAL"}</div>${(t.headlines||[]).slice(0,2).map(h=>`<div class="global-headline">${h.title}${h.source?` · ${h.source}`:""}</div>`).join("")}</div>`).join("")}</div><div class="trend-source">Global themes are supporting evidence only; BUY/HOLD/SELL also uses company, price, risk, ASX announcements and short-interest signals.</div>`:`<div class="company">No material global trend exposure is currently mapped to this company.</div>`;$("#detailThesis").textContent=s.thesis||"No thesis summary available.";$("#detailCatalyst").textContent=s.catalyst||"No catalyst information available.";$("#detailRisk").textContent=s.riskText||"No risk summary available.";const anns=Array.isArray(s.announcements)?s.announcements:[];$("#detailAnnouncements").innerHTML=anns.length?anns.slice(0,10).map(a=>`<div class="announcement"><div class="announcement-date">${a.date||""}${a.priceSensitive?'<span class="price-sensitive">PRICE SENSITIVE</span>':""}</div><div class="announcement-title">${a.headline||"Announcement"}</div></div>`).join(""):`<div class="empty">No recent ASX announcements captured for this company.</div>`;const m=[["Quality",s.quality??50],["Valuation",s.valuation??50],["Growth",s.growth??50],["Momentum",s.momentum??50],["Catalyst",s.catalystScore??50],["Safety",100-Number(s.risk||0)],["Short adj.",sh.score],["Global trend",Number(s.globalTrendScore||0)]];$("#scoreGrid").innerHTML=m.map(([n,v])=>`<div class="score-box"><div class="score-label">${n}</div><div class="score-value">${Math.round(v)}</div></div>`).join("");const h=Array.isArray(s.history)?s.history:[];$("#timeline").innerHTML=h.length?h.slice().reverse().map(e=>`<div class="event"><div class="event-date">${e[0]}</div><div class="event-text">${e[1]}</div><div class="company">${e[2]}</div></div>`).join(""):`<div class="empty">No recorded score changes yet.</div>`;showPage("detail")}'''
s, n = pat.subn(new_open, s, count=1)
if n != 1:
    raise SystemExit(f'openDetail replace count {n}')

p.write_text(s, encoding='utf-8')
print('patched richer company analysis')
